using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Text.Json;
using System.Text.Json.Serialization;
using GestaoClubes.Core;
using SQLite;
using System.Globalization;
using RoundRectangle = Microsoft.Maui.Controls.Shapes.RoundRectangle;
namespace GestaoClubes.Mobile;
public class PublicCache { [PrimaryKey] public int ClubId {get;set;} public string Events {get;set;}="[]"; public DateTime UpdatedUtc {get;set;} }
public partial class MainPage:ContentPage {
 readonly Entry server=new(){Text="http://10.0.2.2:5281",Placeholder="Endereço API"};
 readonly Entry club=new(){Text="1",Placeholder="ID do clube",Keyboard=Keyboard.Numeric};
 readonly Entry email=new(){Placeholder="E-mail",Keyboard=Keyboard.Email};
 readonly Entry password=new(){Placeholder="Senha",IsPassword=true};
 readonly Picker clubPicker=new(){Title="Selecione seu clube",TextColor=Color.FromArgb("143E45")};
 readonly VerticalStackLayout results=new(){Spacing=12};
 bool signedIn;
 record ClubChoice(int Id,string Name){public override string ToString()=>Name;}
 readonly Label output=new(){Text="Entre para consultar seus vínculos. Eventos públicos podem ser consultados offline após atualização."};
 readonly VerticalStackLayout body=new(){Spacing=12,Padding=22};
 readonly SQLiteAsyncConnection cache=new(Path.Combine(FileSystem.AppDataDirectory,"clubs-public.db3"));
 static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web){Converters={new JsonStringEnumConverter()}};
 public MainPage(){InitializeComponent();Application.Current!.UserAppTheme=AppTheme.Light;BackgroundColor=Color.FromArgb("F3F7F7");Title="GestaoClubes";Content=new ScrollView{Content=body};
  clubPicker.SelectedIndexChanged+=(_,_)=>{if(clubPicker.SelectedItem is ClubChoice selected)club.Text=selected.Id.ToString();};
  Loaded+=async(_,_)=>{if(clubPicker.ItemsSource==null)try{await LoadClubs();}catch{output.Text="Não foi possível carregar os clubes. Confira a conexão em Configurações.";}};
  Home();
 }
 void Heading(string title,string subtitle){body.Add(new Label{Text="GC  /  GESTAOCLUBES",FontSize=12,CharacterSpacing=2,TextColor=Color.FromArgb("24747A"),FontAttributes=FontAttributes.Bold});body.Add(new Label{Text=title,FontSize=30,FontAttributes=FontAttributes.Bold,TextColor=Color.FromArgb("143E45")});body.Add(new Label{Text=subtitle,FontSize=15,TextColor=Color.FromArgb("586F76"),Margin=new Thickness(0,0,0,12)});}
 void AddButton(string text,Func<Task> action){var b=new Button{Text=text,BackgroundColor=Color.FromArgb("146C72"),TextColor=Colors.White,CornerRadius=14,MinimumHeightRequest=50,FontSize=15,FontAttributes=FontAttributes.Bold,Padding=new Thickness(16,12)};
  b.Clicked+=async(_,_)=>{b.IsEnabled=false;output.Text="Carregando…";try{await action();if(output.Text=="Carregando…")output.Text="";}catch(HttpRequestException){output.Text="Não foi possível conectar. Confira se a API está ligada e tente novamente.";}catch(TaskCanceledException){output.Text="A conexão demorou demais. Tente novamente.";}catch(Exception ex){output.Text="Não foi possível concluir: "+ex.Message;}finally{b.IsEnabled=true;}};body.Add(b);}
 async Task LoadClubs(){using var c=Client();var response=await c.GetAsync("/api/public/clubs");response.EnsureSuccessStatusCode();using var doc=JsonDocument.Parse(await response.Content.ReadAsStringAsync());var choices=doc.RootElement.EnumerateArray().Select(x=>new ClubChoice(x.GetProperty("id").GetInt32(),x.GetProperty("name").GetString()??"Clube")).ToList();clubPicker.ItemsSource=choices;clubPicker.SelectedItem=choices.FirstOrDefault(x=>x.Id.ToString()==club.Text)??choices.FirstOrDefault();}
 HttpClient Client(){var url=server.Text?.TrimEnd('/')??"";if(!Uri.TryCreate(url,UriKind.Absolute,out var uri)||uri.Scheme is not("http" or "https"))throw new InvalidOperationException("Endereço inválido.");return new HttpClient{BaseAddress=uri,Timeout=TimeSpan.FromSeconds(15)};}
 async Task<HttpClient> Auth(){var c=Client();var token=await SecureStorage.Default.GetAsync("clubs-token");if(token==null)throw new InvalidOperationException("Entre primeiro.");c.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",token);return c;}
 int ClubId()=>int.TryParse(club.Text,out var id)&&id>0?id:throw new InvalidOperationException("ID do clube inválido.");
 async Task Show(HttpResponseMessage response){var text=await response.Content.ReadAsStringAsync();if(!response.IsSuccessStatusCode){if(response.StatusCode==System.Net.HttpStatusCode.Unauthorized)throw new InvalidOperationException("E-mail ou senha inválidos, ou sessão expirada. Entre novamente.");if(response.StatusCode==System.Net.HttpStatusCode.Forbidden)throw new InvalidOperationException("Seu vínculo precisa estar aprovado e permitir esta operação.");try{using var error=JsonDocument.Parse(text);if(error.RootElement.TryGetProperty("error",out var message))throw new InvalidOperationException(message.GetString());}catch(JsonException){}throw new InvalidOperationException("Operação recusada. Revise os dados e tente novamente.");}results.Clear();if(string.IsNullOrWhiteSpace(text)){output.Text="Pronto! Sua solicitação foi registrada.";return;}using var document=JsonDocument.Parse(text);Render(document.RootElement);output.Text="";}
 static readonly Dictionary<string,string> Labels=new(){["name"]="Nome",["club"]="Clube",["city"]="Cidade",["state"]="UF",["email"]="E-mail",["phone"]="Telefone",["role"]="Perfil",["type"]="Categoria",["status"]="Situação",["canVote"]="Direito a voto",["title"]="Evento",["startUtc"]="Início",["endUtc"]="Término",["space"]="Espaço",["purpose"]="Finalidade",["period"]="Competência",["dueDate"]="Vencimento",["amount"]="Valor",["paidUtc"]="Pagamento registrado",["reference"]="Referência",["total"]="Total lançado",["received"]="Recebido",["outstanding"]="Em aberto",["overdue"]="Vencido",["kind"]="Tipo",["text"]="Mensagem",["response"]="Resposta",["createdUtc"]="Enviado em",["message"]="Informação"};
 string Value(string key,JsonElement value){if(value.ValueKind==JsonValueKind.Null)return key=="paidUtc"?"Em aberto":"Aguardando informação";if(value.ValueKind is JsonValueKind.True or JsonValueKind.False)return value.GetBoolean()?"Sim":"Não";if(new[]{"amount","total","received","outstanding","overdue"}.Contains(key)&&value.TryGetDecimal(out var money))return money.ToString("C",CultureInfo.GetCultureInfo("pt-BR"));if(key.EndsWith("Utc")&&DateTime.TryParse(value.ToString(),CultureInfo.InvariantCulture,DateTimeStyles.AssumeUniversal|DateTimeStyles.AdjustToUniversal,out var date))return date.ToLocalTime().ToString("dd/MM/yyyy HH:mm");if(key=="dueDate"&&DateOnly.TryParse(value.ToString(),out var day))return day.ToString("dd/MM/yyyy");return value.ToString().Replace("SALAO SOCIAL","Salão social").Replace("CHURRASQUEIRA","Churrasqueira").Replace("Reclamacao","Reclamação").Replace("Solicitacao","Solicitação").Replace("EmAtendimento","Em atendimento");}
 void Card(JsonElement row){var content=new VerticalStackLayout{Spacing=10,Padding=18};foreach(var prop in row.EnumerateObject()){if(!Labels.TryGetValue(prop.Name,out var label)||prop.Value.ValueKind is JsonValueKind.Array or JsonValueKind.Object)continue;content.Add(new Label{Text=label.ToUpperInvariant(),FontSize=10,CharacterSpacing=1,TextColor=Color.FromArgb("586F76")});content.Add(new Label{Text=Value(prop.Name,prop.Value),FontSize=16,TextColor=Color.FromArgb("143E45")});}if(content.Children.Count>0)results.Add(new Border{BackgroundColor=Colors.White,Stroke=Color.FromArgb("DCE8E8"),StrokeShape=new RoundRectangle{CornerRadius=new CornerRadius(16)},Content=content});}
 void Render(JsonElement data){if(data.ValueKind==JsonValueKind.Array){if(data.GetArrayLength()==0)results.Add(new Label{Text="Tudo em dia por aqui. Nenhum registro encontrado.",TextColor=Color.FromArgb("586F76"),Margin=16});foreach(var row in data.EnumerateArray())if(row.ValueKind==JsonValueKind.Object)Card(row);return;}if(data.ValueKind!=JsonValueKind.Object)return;Card(data);foreach(var key in new[]{"memberships","charges"})if(data.TryGetProperty(key,out var rows))Render(rows);}
 void ResultPage(string title){body.Clear();results.Clear();Heading(title,"Informações do clube selecionado");AddButton("← Voltar ao início",()=>{Home();return Task.CompletedTask;});body.Add(output);body.Add(results);}
 async Task Query(string title,string route,bool authenticated=true){using var c=authenticated?await Auth():Client();ResultPage(title);await Show(await c.GetAsync(route));}
 void Home(){body.Clear();results.Clear();Heading(signedIn?"Seu clube, perto de você":"Bem-vindo ao clube",signedIn?"Acompanhe suas atividades e cuide do que importa.":"Entre para acompanhar reservas, eventos e mensalidades.");body.Add(new Label{Text="CLUBE",FontSize=11,TextColor=Color.FromArgb("586F76")});body.Add(clubPicker);
  if(!signedIn){body.Add(new Label{Text="E-mail",TextColor=Color.FromArgb("143E45")});body.Add(email);body.Add(new Label{Text="Senha",TextColor=Color.FromArgb("143E45")});body.Add(password);AddButton("Entrar na minha conta",async()=>{using var c=Client();var response=await c.PostAsJsonAsync("/api/auth/login",new LoginRequest(email.Text?.Trim()??"",password.Text??""),Json);if(!response.IsSuccessStatusCode){await Show(response);return;}var token=await response.Content.ReadFromJsonAsync<TokenResponse>(Json);await SecureStorage.Default.SetAsync("clubs-token",token!.Token);password.Text="";signedIn=true;Home();output.Text="Você entrou. Selecione seu clube para continuar.";});}
  if(signedIn){AddButton("Meu vínculo e aprovação",()=>Query("Meu vínculo","/api/me"));AddButton("Meus eventos",()=>Query("Eventos do clube",$"/api/clubs/{ClubId()}/events"));AddButton("Mensalidades",()=>Query("Mensalidades",$"/api/clubs/{ClubId()}/finance"));AddButton("Minhas reservas",()=>Query("Minhas reservas",$"/api/clubs/{ClubId()}/reservations"));AddButton("Reservar um espaço",()=>{ReservationForm();return Task.CompletedTask;});AddButton("Solicitações e reclamações",()=>{TicketForm();return Task.CompletedTask;});}
  AddButton("Eventos abertos · online e offline",async()=>{await cache.CreateTableAsync<PublicCache>();var id=ClubId();ResultPage("Eventos abertos");try{using var c=Client();var response=await c.GetAsync($"/api/public/clubs/{id}/events");response.EnsureSuccessStatusCode();var text=await response.Content.ReadAsStringAsync();await cache.InsertOrReplaceAsync(new PublicCache{ClubId=id,Events=text,UpdatedUtc=DateTime.UtcNow});Render(JsonDocument.Parse(text).RootElement);output.Text="Atualizado agora · horários locais";}catch(HttpRequestException){await Cached(id);}catch(TaskCanceledException){await Cached(id);}});
  if(!signedIn)AddButton("Quero fazer parte · solicitar cadastro",()=>{RegisterForm();return Task.CompletedTask;});
  AddButton("Configurações de conexão",()=>{body.Clear();Heading("Conexão","Endereço do servidor usado pelo aplicativo");body.Add(server);AddButton("Salvar e atualizar clubes",async()=>{await LoadClubs();Home();output.Text="Conexão atualizada.";});Back();return Task.CompletedTask;});
  if(signedIn)AddButton("Sair da conta",async()=>{SecureStorage.Default.Remove("clubs-token");await cache.CreateTableAsync<PublicCache>();await cache.DeleteAllAsync<PublicCache>();signedIn=false;Home();output.Text="Você saiu da conta.";});body.Add(output);body.Add(results);
 }
 async Task Cached(int id){var row=await cache.FindAsync<PublicCache>(id);output.Text=row==null?"Sem conexão e sem eventos salvos para este clube.":$"Modo offline · atualizado em {row.UpdatedUtc.ToLocalTime():dd/MM/yyyy HH:mm}";if(row!=null)Render(JsonDocument.Parse(row.Events).RootElement);}
 static string CpfMask(string value){var digits=new string(value.Where(char.IsAsciiDigit).Take(11).ToArray());var text=new System.Text.StringBuilder();for(var i=0;i<digits.Length;i++){if(i is 3 or 6)text.Append('.');if(i==9)text.Append('-');text.Append(digits[i]);}return text.ToString();}
 void MaskCpf(Entry field){field.Placeholder="000.000.000-00";field.Keyboard=Keyboard.Numeric;field.MaxLength=14;field.TextChanged+=(_,args)=>{var raw=args.NewTextValue??"";var formatted=CpfMask(raw);if(raw==formatted)return;var before=raw.Take(Math.Min(field.CursorPosition,raw.Length)).Count(char.IsAsciiDigit);var cursor=0;var seen=0;while(cursor<formatted.Length&&seen<before){if(char.IsAsciiDigit(formatted[cursor]))seen++;cursor++;}field.Text=formatted;field.CursorPosition=cursor;};}
 Entry Field(string title,bool secret=false){body.Add(new Label{Text=title});var e=new Entry{Placeholder=title,IsPassword=secret};body.Add(e);return e;}
 void Back(){AddButton("Voltar",()=>{Home();return Task.CompletedTask;});body.Add(output);body.Add(results);}
 void ReservationForm(){body.Clear();results.Clear();Heading("Reserve seu espaço","Escolha o período em horário local. A reserva será analisada pelo clube.");var space=new Picker{Title="Espaço",ItemsSource=new[]{"Salão social","Churrasqueira"},SelectedIndex=0};body.Add(space);var purpose=Field("O que você está planejando?");body.Add(new Label{Text="Início"});var startDate=new DatePicker{Date=DateTime.Today.AddDays(1),MinimumDate=DateTime.Today,Format="dd/MM/yyyy"};var startTime=new TimePicker{Time=new TimeSpan(12,0,0),Format="HH:mm"};body.Add(startDate);body.Add(startTime);body.Add(new Label{Text="Término"});var endDate=new DatePicker{Date=DateTime.Today.AddDays(1),MinimumDate=DateTime.Today,Format="dd/MM/yyyy"};var endTime=new TimePicker{Time=new TimeSpan(18,0,0),Format="HH:mm"};body.Add(endDate);body.Add(endTime);
 AddButton("Solicitar reserva",async()=>{var s=startDate.Date!.Value.Date.Add(startTime.Time!.Value).ToUniversalTime();var e=endDate.Date!.Value.Date.Add(endTime.Time!.Value).ToUniversalTime();using var c=await Auth();await Show(await c.PostAsJsonAsync($"/api/clubs/{ClubId()}/reservations",new ReservationInput(space.SelectedIndex==0?"SALAO SOCIAL":"CHURRASQUEIRA",purpose.Text??"",s,e),Json));});Back();}
 void TicketForm(){body.Clear();results.Clear();Heading("Vamos conversar","Envie uma solicitação ou reclamação e acompanhe a resposta.");var kind=new Picker{Title="Tipo",ItemsSource=new[]{"Solicitacao","Reclamacao"},SelectedIndex=0};body.Add(kind);var text=new Editor{Placeholder="Mensagem",HeightRequest=150,MaxLength=2000};body.Add(text);AddButton("Enviar online",async()=>{using var c=await Auth();await Show(await c.PostAsJsonAsync($"/api/clubs/{ClubId()}/tickets",new TicketInput((string)kind.SelectedItem,text.Text??""),Json));});AddButton("Consultar respostas",async()=>{using var c=await Auth();await Show(await c.GetAsync($"/api/clubs/{ClubId()}/tickets"));});Back();}
 void RegisterForm(){body.Clear();results.Clear();body.Add(new Label{Text="Cadastro sujeito à aprovação",FontSize=23});var name=Field("Nome");var e=Field("E-mail");var pw=Field("Senha (12 caracteres ou mais)",true);var cpf=Field("CPF");MaskCpf(cpf);var birth=Field("Nascimento (DD/MM/AAAA ou AAAA-MM-DD)");var address=Field("Endereço");var district=Field("Bairro");var city=Field("Cidade");var state=Field("UF maiúscula");var phone=Field("Telefone");var sex=Field("Sexo (opcional)");var marital=Field("Estado civil (opcional)");var interests=Field("Interesses (opcional)");var type=new Picker{Title="Tipo",ItemsSource=new[]{"Associado","Convidado","Simpatizante"},SelectedIndex=0};body.Add(type);
 body.Add(new Label{Text="Dados usados para identificação e serviços do clube. CPF e nascimento têm acesso restrito. Solicite acesso, correção ou exclusão ao clube. Use apenas dados fictícios nesta demonstração."});var accepted=new CheckBox{Color=Color.FromArgb("146C72")};var consent=new HorizontalStackLayout{Spacing=8};consent.Add(accepted);consent.Add(new Label{Text="Li a informação de privacidade\ne solicito meu cadastro",VerticalOptions=LayoutOptions.Center,TextColor=Color.FromArgb("143E45"),FontSize=14});body.Add(consent);
 AddButton("Enviar cadastro online",async()=>{if(!accepted.IsChecked)throw new InvalidOperationException("Marque a caixa de leitura da informação de privacidade.");if(!Rules.ValidCpf(cpf.Text))throw new InvalidOperationException("CPF inválido. Confira os 11 dígitos; números inventados podem ter dígitos verificadores incorretos.");if(!DateOnly.TryParseExact(birth.Text?.Trim(),new[]{"dd/MM/yyyy","yyyy-MM-dd"},CultureInfo.InvariantCulture,DateTimeStyles.None,out var date)||!Rules.ValidBirth(date))throw new InvalidOperationException("Nascimento inválido. Use DD/MM/AAAA (exemplo: 15/06/1990), sem data futura.");var input=new RegisterRequest(ClubId(),name.Text??"",e.Text??"",pw.Text??"",Enum.Parse<MemberType>((string)type.SelectedItem),cpf.Text??"",date,address.Text??"",district.Text??"",city.Text??"",state.Text??"",phone.Text??"",sex.Text??"",marital.Text??"",interests.Text??"",accepted.IsChecked);using var c=Client();await Show(await c.PostAsJsonAsync("/api/auth/register",input,Json));pw.Text="";});Back();}
}
